import React from "react";
import "./Navbar.css"; // Ensure you have the updated CSS file

const Navbar = ({ setActivePage }) => {
  return (
    <nav className="navbar">
      <ul>
        <li onClick={() => setActivePage("chat")}>💬 Chat</li>
        <li onClick={() => setActivePage("youtube")}>📺 YouTube</li>
        <li onClick={() => setActivePage("wikipedia")}>📖 Wikipedia</li>
        <li onClick={() => setActivePage("test")}>📝 Test</li>
      </ul>
    </nav>
  );
};

export default Navbar;
